const pending = new Map();                       // id -> { resolve, reject, timer }

function call(payload, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    const id = crypto.randomUUID();
    const timer = setTimeout(() => {
      pending.delete(id);
      reject(new Error(`no reply for ${id}`));   // deadline path
    }, timeoutMs);
    pending.set(id, { resolve, reject, timer }); // register BEFORE send
    socket.send(JSON.stringify({ id, payload }));
  });
}
socket.on('message', (raw) => {
  const msg = JSON.parse(raw);
  const entry = pending.get(msg.id);
  if (!entry) return;                            // unknown or late id: drop
  pending.delete(msg.id); clearTimeout(entry.timer); entry.resolve(msg.payload);
});
